const googleEvents = $('Get many events').all().map(i => i.json);
const outlookEvents = $('Get many events Outlook').all().map(i => i.json);
const tournage = $input.first().json;

let totalMinutes = 0;

for (const event of googleEvents) {
  if (!event.start?.dateTime || !event.end?.dateTime) continue;
  const start = new Date(event.start.dateTime);
  const end = new Date(event.end.dateTime);
  totalMinutes += (end - start) / 1000 / 60;
}

for (const event of outlookEvents) {
  if (!event.start?.dateTime || !event.end?.dateTime) continue;
  const start = DateTime.fromISO(event.start.dateTime, { zone: 'utc' }).setZone('Europe/Paris');
  const end = DateTime.fromISO(event.end.dateTime, { zone: 'utc' }).setZone('Europe/Paris');
  totalMinutes += end.diff(start, 'minutes').minutes;
}

const totalHours = totalMinutes / 60;
const majorationReunions = totalHours > 4 ? 0.2 : 0;
const majorationTerrain = tournage.tournage_martin_aujourdhui ? 0.3 : 0;
const poidsJournee = 1.0 + majorationReunions + majorationTerrain;

return [{
  json: {
    date: $now.setZone('Europe/Paris').toISODate(),
    poids_journee: poidsJournee,
    signaux: {
      total_heures_reunions: Math.round(totalHours * 10) / 10,
      journee_dense: majorationReunions > 0,
      journee_terrain: majorationTerrain > 0,
      terrain_source: majorationTerrain > 0 ? (tournage.source_monday_item_name || 'Monday') : null,
      nb_evenements_google: googleEvents.length,
      nb_evenements_outlook: outlookEvents.length
    }
  }
}];

// Roster : prénom détecté dans le nom de l'item -> nom complet (D34)
const ROSTER = {
  THOMAS: 'Thomas Clicteur',
  ANTOINE: 'Antoine Paley',
  CHARLYNE: 'Charlyne Féneant',
  LISA: 'Lisa Mazal',
  MAELLE: 'Maëlle Das Neves',
  MAËLLE: 'Maëlle Das Neves'
};

// Jours normalement présentiel (rythme D34, en vigueur depuis le 13/10/2025)
// JS getUTCDay() : 0=dimanche, 1=lundi, 2=mardi, 3=mercredi, 4=jeudi, 5=vendredi, 6=samedi
const JOURS_PRESENTIEL = [3, 4];

function toTokens(str) {
  return (str || '').toUpperCase().split(/[^A-ZÀ-Ÿ]+/).filter(Boolean);
}

function findColumn(columnValues, title) {
  return columnValues.find(c => c.column && c.column.title === title);
}

function datesInRange(fromStr, toStr) {
  const dates = [];
  let current = new Date(fromStr + 'T00:00:00Z');
  const end = new Date(toStr + 'T00:00:00Z');
  while (current <= end) {
    dates.push(current.toISOString().slice(0, 10));
    current.setUTCDate(current.getUTCDate() + 1);
  }
  return dates;
}

const results = [];

for (const inputItem of $input.all()) {
  const item = inputItem.json;
  const columnValues = item.column_values || [];

  const statutCol = findColumn(columnValues, 'Statut Prod');
  const statut = statutCol ? statutCol.text : null;

  if (statut !== 'Absence') {
    continue; // sécurité : normalement déjà filtré en amont par le node Monday
  }

  const tokens = toTokens(item.name);
  const isTT = tokens.includes('TT'); // exclut naturellement RTT (token différent) — D35

  if (!isTT) {
    continue; // pas un TT (RTT, congé, école, formation... hors scope D33)
  }

  const personToken = tokens.find(t => ROSTER[t]);
  const personne = personToken ? ROSTER[personToken] : null;

  if (!personne) {
    results.push({
      json: {
        _statut: 'ambigu',
        _raison: 'Item classé TT mais aucune personne du roster reconnue dans le nom',
        source_monday_item_id: item.id,
        source_monday_item_name: item.name
      }
    });
    continue;
  }

  // Récupérer la période (avec filet de sécurité sur Date de tournage — cas TT_MAELLE)
  const periodeCol = findColumn(columnValues, 'Période');
  let from = null, to = null;

  if (periodeCol && periodeCol.value) {
    const parsed = JSON.parse(periodeCol.value);
    from = parsed.from;
    to = parsed.to;
  } else {
    const dateTournageCol = findColumn(columnValues, 'Date de tournage');
    if (dateTournageCol && dateTournageCol.value) {
      const parsed = JSON.parse(dateTournageCol.value);
      from = parsed.date;
      to = parsed.date;
    }
  }

  if (!from || !to) {
    results.push({
      json: {
        _statut: 'ambigu',
        _raison: 'Item classé TT mais aucune date exploitable (ni Période ni Date de tournage)',
        source_monday_item_id: item.id,
        source_monday_item_name: item.name
      }
    });
    continue;
  }

  // Un événement "tt_exceptionnel" par jour normalement présentiel couvert par la période
  for (const date of datesInRange(from, to)) {
    const jour = new Date(date + 'T00:00:00Z').getUTCDay();
    if (JOURS_PRESENTIEL.includes(jour)) {
      results.push({
        json: {
          personne,
          date,
          type: 'tt_exceptionnel',
          source_monday_item_id: item.id,
          source_monday_item_name: item.name
        }
      });
    }
  }
}

return results;

const response = $input.first().json;
const page = response.data.boards[0].items_page;
return [{
  json: {
    items: page.items,
    cursor: page.cursor
  }
}];

const page1Items = $('Extraire page 1').item.json.items;
const page2Response = $input.first().json;
const page2Items = page2Response.data.next_items_page.items;

const allItems = [...page1Items, ...page2Items];

return allItems.map(item => ({ json: item }));

const ROSTER = {
  THOMAS: 'Thomas Clicteur',
  ANTOINE: 'Antoine Paley',
  CHARLYNE: 'Charlyne Féneant',
  LISA: 'Lisa Mazal',
  MAELLE: 'Maëlle Das Neves',
  MAËLLE: 'Maëlle Das Neves',
  MARTIN: 'Martin Pavloff',
  MPAVLOFF: 'Martin Pavloff'
};

const RYTHMES = [
  { depuis: '2025-10-13', jours_tt: [1, 2, 5] },
  { depuis: '2024-09-01', jours_tt: [1, 4, 5] }
];

const POLES_EXCLUS = ['STUDYADVISOR', 'SOLO REDAC', 'POLE ?'];

function joursTTPourDate(date) {
  for (const rythme of RYTHMES) {
    if (date >= rythme.depuis) return rythme.jours_tt;
  }
  return null;
}

function normalize(str) {
  return (str || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function toTokens(str) {
  return normalize(str).split(/[^A-Z]+/).filter(Boolean);
}

function findColumn(columnValues, title) {
  return columnValues.find(c => c.column && c.column.title === title);
}

function matchRoster(text) {
  const tokens = toTokens(text);
  if (tokens.includes('VASSAS')) return null;
  const token = tokens.find(t => ROSTER[t]);
  return token ? ROSTER[token] : null;
}

const results = [];

for (const inputItem of $input.all()) {
  const item = inputItem.json;
  const columnValues = item.column_values || [];

  // Filtre Pôles : on ignore les tournages où la Cellule Vidéo n'intervient pas
  const polesCol = findColumn(columnValues, 'Pôles');
  const poleNorm = normalize(polesCol ? polesCol.text : '');
  if (POLES_EXCLUS.includes(poleNorm)) continue;

  const statutCol = findColumn(columnValues, 'Statut Prod');
  const statut = statutCol ? statutCol.text : null;
  if (!statut || statut === 'Absence') continue;

  const dateCol = findColumn(columnValues, 'Date de tournage');
  if (!dateCol || !dateCol.value) continue;

  const parsedDate = JSON.parse(dateCol.value);
  const date = parsedDate.date;
  if (!date) continue;

  const joursTT = joursTTPourDate(date);
  if (!joursTT) continue;

  const jour = new Date(date + 'T00:00:00Z').getUTCDay();
  if (!joursTT.includes(jour)) continue;

  const respCol = findColumn(columnValues, 'Resp. Tournage');
  const respText = respCol ? respCol.text : '';

  const personnesTrouvees = new Set();

  if (respText && respText.trim() !== '') {
    const fragments = respText.split(',').map(f => f.trim()).filter(Boolean);
    for (const fragment of fragments) {
      const personne = matchRoster(fragment);
      if (personne) personnesTrouvees.add(personne);
    }
  }

  if (personnesTrouvees.size === 0) {
    const backupCol = findColumn(columnValues, 'Responsable Backup');
    const backupText = backupCol ? backupCol.text : '';
    const personne = matchRoster(backupText);
    if (personne) personnesTrouvees.add(personne);
  }

  if (personnesTrouvees.size > 0) {
    for (const personne of personnesTrouvees) {
      results.push({
        json: {
          personne,
          date,
          type: 'presentiel_exceptionnel',
          confirme: true,
          source_monday_item_id: item.id,
          source_monday_item_name: item.name
        }
      });
    }
  } else {
    // Personne identifiée -> attribution par défaut à Martin, marquée non confirmée
    results.push({
      json: {
        personne: 'Martin Pavloff',
        date,
        type: 'presentiel_exceptionnel',
        confirme: false,
        source_monday_item_id: item.id,
        source_monday_item_name: item.name
      }
    });
  }
}

return results;

function normalize(str) {
  return (str || '').toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
}
function toTokens(str) {
  return normalize(str).split(/[^A-Z]+/).filter(Boolean);
}
function findColumn(columnValues, title) {
  return columnValues.find(c => c.column && c.column.title === title);
}
function matchMartin(text) {
  const tokens = toTokens(text);
  return tokens.includes('MARTIN') || tokens.includes('MPAVLOFF');
}

const POLES_EXCLUS = ['STUDYADVISOR', 'SOLO REDAC', 'POLE ?'];
const today = $now.setZone('Europe/Paris').toISODate();

const tournagesTrouves = [];

for (const inputItem of $input.all()) {
  const item = inputItem.json;
  const columnValues = item.column_values || [];

  const polesCol = findColumn(columnValues, 'Pôles');
  const poleNorm = normalize(polesCol ? polesCol.text : '');
  if (POLES_EXCLUS.includes(poleNorm)) continue;

  const statutCol = findColumn(columnValues, 'Statut Prod');
  const statut = statutCol ? statutCol.text : null;
  if (!statut || statut === 'Absence') continue;

  const dateCol = findColumn(columnValues, 'Date de tournage');
  if (!dateCol || !dateCol.value) continue;
  const parsedDate = JSON.parse(dateCol.value);
  if (parsedDate.date !== today) continue;

  const respCol = findColumn(columnValues, 'Resp. Tournage');
  const respText = respCol ? respCol.text : '';
  const backupCol = findColumn(columnValues, 'Responsable Backup');
  const backupText = backupCol ? backupCol.text : '';

  if (!matchMartin(respText) && !matchMartin(backupText)) continue;

  const lieuCol = findColumn(columnValues, 'Lieu');

  tournagesTrouves.push({
    tournage_martin_aujourdhui: true,
    source_monday_item_name: item.name,
    heure_debut: parsedDate.time || null,
    lieu: lieuCol ? lieuCol.text : null
  });
}

if (tournagesTrouves.length === 0) {
  return [{
    json: {
      tournage_martin_aujourdhui: false,
      source_monday_item_name: null,
      heure_debut: null,
      lieu: null
    }
  }];
}

return tournagesTrouves.map(t => ({ json: t }));

const googleEvents = $('Get many events').all().map(i => i.json);
const outlookEvents = $('Get many events Outlook').all().map(i => i.json);

const results = [];

for (const event of googleEvents) {
  if (!event.id) continue;
  const titre = event.summary || '(sans titre)';
  const description = event.description || '';
  const debut = event.start?.dateTime || event.start?.date || '';
  const lieu = event.location || '';
  results.push({
    json: {
      event_id: event.id,
      event_source: 'google',
      event_date: debut,
      signal_texte: `Titre : ${titre}\nDescription : ${description}\nDébut : ${debut}\nLieu : ${lieu}`
    }
  });
}

for (const event of outlookEvents) {
  if (!event.id) continue;
  const titre = event.subject || '(sans titre)';
  const description = event.bodyPreview || '';
  const debutUTC = event.start?.dateTime || '';
  const debutParis = debutUTC
    ? DateTime.fromISO(debutUTC, { zone: 'utc' }).setZone('Europe/Paris')
    : null;
  const debutAffiche = debutParis ? debutParis.toISO() : '';
  const lieu = event.location?.displayName || '';
  results.push({
    json: {
      event_id: event.id,
      event_source: 'outlook',
      event_date: debutAffiche,
      signal_texte: `Titre : ${titre}\nDescription : ${description}\nDébut : ${debutAffiche}\nLieu : ${lieu}`
    }
  });
}

const gmailMessages = $('Get many messages Gmail').all().map(i => i.json);

for (const msg of gmailMessages) {
  if (!msg.id) continue;

  const sujet = msg.subject || '(sans objet)';
  const expediteur = msg.from?.text || msg.from?.value?.[0]?.address || '';
  const apercu = (msg.text || msg.snippet || '').slice(0, 300);
  const dateUTC = msg.date || '';
  const dateParis = dateUTC
    ? DateTime.fromISO(dateUTC, { zone: 'utc' }).setZone('Europe/Paris').toISO()
    : '';
  const labelIds = msg.labelIds || [];
  const estNewsletter = labelIds.includes('CATEGORY_PROMOTIONS');
  const headerUnsubscribe = msg.headers?.['list-unsubscribe'] || '';
  const lienDesabonnement = headerUnsubscribe.replace(/^List-Unsubscribe:\s*/i, '');
  const signalNewsletter = estNewsletter
    ? `\nSignal newsletter/pub détecté (Gmail) : oui${lienDesabonnement ? ` — lien de désabonnement : ${lienDesabonnement}` : ''}`
    : '';

  results.push({
    json: {
      event_id: msg.id,
      event_source: 'gmail',
      event_date: dateParis,
      signal_texte: `Objet : ${sujet}\nExpéditeur : ${expediteur}\nAperçu : ${apercu}\nReçu le : ${dateParis}${signalNewsletter}`
    }
  });
}

return results;

parameters.jsonBody:
={{ JSON.stringify({
  model: "ministral-3:8b",
  stream: false,
  format: {
    type: "object",
    properties: {
      azimut: { type: "string", enum: ["calendrier_temps","boite_mail","sante","famille_proches","loisirs","finances_perso","domicile","management_equipe"] },
      est_un_point: { type: "boolean" },
      resume: { type: "string" },
      urgence: { type: "integer", minimum: 1, maximum: 5 },
      urgence_label: { type: "string", enum: ["faible","normale","élevée","très élevée","critique"] },
      action_suggeree: { type: "string" }
    },
    required: ["azimut","est_un_point","resume","urgence","urgence_label","action_suggeree"]
  },
  messages: [
    { role: "system", content: "Tu es le moteur d'interprétation de Perimeter, l'outil personnel de Martin Pavloff (directeur de la Cellule Vidéo, L'Étudiant). Ta mission : lire un signal brut (un mail ou un événement de calendrier) et le transformer en un point structuré, rattaché à l'un des azimuts suivants.\n\nAZIMUTS POSSIBLES :\n- calendrier_temps — charge de la journée, présentiel/télétravail\n- boite_mail — tri, relances, deadlines cachées dans un mail\n- sante — rendez-vous médicaux, suivi santé\n- famille_proches — événements ou échéances familiales\n- loisirs — activités personnelles, réservations, sorties\n- finances_perso — factures, relances, échéances financières personnelles\n- domicile — rendez-vous artisans, livraisons, travaux\n- management_equipe — 1-to-1, tension avec un collaborateur, feedback en attente\n\nRÈGLES :\n1. Choisis toujours l'azimut le plus proche, même si l'événement n'est pas un vrai point de vigilance.\n2. est_un_point vaut true seulement si l'événement représente un vrai point de vigilance nécessitant une action ou un suivi de la part de Martin. Il vaut false si c'est un événement anodin, routinier, ou sans action requise.\n3. Le résumé tient en une phrase, factuelle, sans reformulation stylée.\n4. L'urgence est un entier de 1 à 5 : 1 = aucune urgence perceptible, 3 = à traiter dans la semaine, 5 = à traiter aujourd'hui ou dépassé. Si est_un_point est false, mets toujours urgence à 1.\n5. Le label d'urgence suit strictement l'échelle : 1 = \"faible\", 2 = \"normale\", 3 = \"élevée\", 4 = \"très élevée\", 5 = \"critique\".\n6. Si est_un_point est false, action_suggeree doit valoir exactement \"Aucune action nécessaire\"." },
    { role: "user", content: $json.signal_texte }
  ]
}) }}

